export const articles=[
 {slug:'from-idea-to-mvp',title:'From an idea to an MVP: what to build first',category:'Product engineering',readTime:'5 min read',intro:'Your first release needs to answer a clear question. Define what you need to learn, then build the shortest path to that evidence.',sections:[['Begin with one user and one problem','Describe the person using the product and the job they are trying to complete. A specific problem makes it easier to decide what belongs in the first release.'],['Scope a complete journey','Choose one journey that works from beginning to end. A booking product should let someone choose a service, submit a request, and understand what happens next.'],['Keep the engineering practical','Choose familiar tools and document key decisions. Build error states alongside the happy path. Put secrets on the server and add access controls before storing customer information.'],['Agree how you will learn','Did users complete the task? Where did they need help? Review a small number of questions after launch and use the evidence to decide the next improvement.']]},
 {slug:'rag-before-fine-tuning',title:'Working with your own data: a practical guide to RAG',category:'AI & machine learning',readTime:'6 min read',intro:'A useful document assistant starts with clear data and careful evaluation. Retrieval gives a language model relevant context at the moment it answers.',sections:[['Start with the source documents','Use documents you can lawfully process and make access permissions explicit. Preserve document names and section titles so answers can refer back to their sources.'],['Build a retrieval baseline','Split text along sensible boundaries and inspect retrieved passages. Measure whether the right evidence appears before optimizing the generation step.'],['Design for missing evidence','Some questions will not have an answer in your documents. Give the system a way to say this and check that it distinguishes unsupported guesses from grounded answers.'],['Evaluate the complete workflow','Maintain representative questions, including ambiguous and unanswerable ones. Review citations, permissions, latency, and cost before sharing the tool.']]},
 {slug:'better-debugging-habits',title:'A calmer, more effective way to debug your code',category:'Developer guides',readTime:'4 min read',intro:'Debugging becomes easier when you turn a vague failure into a small, repeatable experiment.',sections:[['Make the failure repeatable','Record the input, environment, expected result, and actual result. A minimal reproduction removes unrelated details and gives you a reliable way to check a change.'],['Form one testable explanation','Read the error and follow values through the failing path. Change one thing at a time and predict what should happen if your explanation is correct.'],['Use your tools deliberately','Breakpoints, structured logs, and assertions reveal different evidence. Avoid logging secrets or customer information.'],['Check the boundaries','Check nearby edge cases after fixing the immediate bug. Record the reason for the change and add a focused regression test when the failure could return.']]},
 {slug:'portfolio-project-guide',title:'Build a portfolio project you can explain with confidence',category:'Learning & careers',readTime:'5 min read',intro:'A good portfolio explains your decisions, your contribution, and how the application works. Focus on substance and clarity.',sections:[['Choose a problem you understand','A small everyday problem gives your project context. Explain who it helps, what it does, and which trade-offs you chose.'],['Finish the everyday details','Loading, empty, error, and success states show thought about actual usage. Validate inputs, support small screens, and make controls keyboard accessible.'],['Write a useful README','Explain setup, environment requirements, architecture, and known limitations. Provide synthetic data so someone can try the application safely.'],['Practice the walkthrough','Show the main journey and explain one challenging decision. Be clear about tutorials, libraries, and collaborators you relied on.']]},
];
